const typeStyle=document.createElement('style');typeStyle.textContent='.cw-game,.cw-game *{font-family:var(--gamefont),Arial,sans-serif!important}.cw-game button{background:var(--button-bg)!important;color:var(--button-text)!important;border-color:var(--button-bg)!important}.cw-game .cw-cell input{color:var(--letter-color)}';const selectors={grid:'.cw-cell input',numbers:'.cw-cell small',title:'.cw-title',clue:'.cw-clue p',buttons:'.cw-button',bubble:'.cw-bubble',final:'.cw-final p'};for(const [role,t]of Object.entries(p.typography||{})){if(!selectors[role])continue;let rules=[];if(t.family)rules.push('font-family:'+JSON.stringify(String(t.family))+',Arial,sans-serif');if(t.size)rules.push('font-size:'+Math.max(8,Math.min(80,Number(t.size)||12))+'px');if(/^#[a-f0-9]{6}$/i.test(t.color||''))rules.push('color:'+t.color);if(t.bold)rules.push('font-weight:700');if(t.italic)rules.push('font-style:italic');if(t.spacing)rules.push('letter-spacing:'+Math.max(0,Math.min(10,Number(t.spacing)||0))+'px');if(t.line)rules.push('line-height:'+Math.max(1,Math.min(3,Number(t.line)||1.4)));if(t.shadow)rules.push('text-shadow:0 1px 2px #0002');typeStyle.textContent+='.cw-game '+selectors[role]+'{'+rules.map(r=>r+'!important').join(';')+'}';}host.append(typeStyle);root.CrosswordFonts?.loadProject(p).catch(()=>{});if(p.customFont&&typeof FontFace!=='undefined'){const font=new FontFace('Мой шрифт','url('+p.customFont+')');font.load().then(f=>document.fonts.add(f)).catch(()=>{});}const game=host.querySelector('.cw-game'),grid=host.querySelector('.cw-grid'),bubble=host.querySelector('.cw-bubble');const color=(v,f)=>/^#[a-f0-9]{6}$/i.test(v||'')?v:f;game.style.setProperty('--accent',color(p.accent,'#426347'));game.style.setProperty('--bg',color(p.background,'#fbf3e3'));game.style.setProperty('--radius',Math.max(0,Math.min(12,+p.radius||0))+'px');game.style.setProperty('--gamefont',JSON.stringify(p.gridFont||'Georgia'));game.style.setProperty('--letter-color',color(p.letterColor,'#35553a'));game.style.setProperty('--button-bg',color(p.buttonColor,p.accent||'#426347'));game.style.setProperty('--button-text',color(p.buttonTextColor,'#fffdf4'));host.querySelector('.cw-cat-image').style.transform='scale('+Math.max(.5,Math.min(1.4,Number(p.catScale)||1))+') scaleX('+(p.catMirror?-1:1)+')';for(const [action,style]of Object.entries(p.buttonStyles||{})){if(!['check','hint','keyboard','keys','next','play','retry'].includes(action))continue;let rules=[];for(const [key,prop]of [['background','background'],['text','color'],['border','border-color']])if(/^#[a-f0-9]{6}$/i.test(style[key]||''))rules.push(prop+':'+style[key]+'!important');typeStyle.textContent+='.cw-game button[data-action="'+action+'"]{'+rules.join(';')+'}';}let map=new Map();for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){let k=r+','+c,q=b.get(k);let d=document.createElement('div');if(!q){d.className='cw-empty';if(options.onDropWord){d.style.visibility='visible';d.style.border='1px dashed #afba9640';d.addEventListener('dragover',e=>e.preventDefault());d.addEventListener('drop',e=>{e.preventDefault();options.onDropWord(e.dataTransfer.getData('text/plain'),r,c);});}grid.append(d);continue;}d.className='cw-cell';if(options.onDropWord){d.addEventListener('dragover',e=>e.preventDefault());d.addEventListener('drop',e=>{e.preventDefault();options.onDropWord(e.dataTransfer.getData('text/plain'),r,c);});}let num=words.filter(w=>w.r===r&&w.c===c).map(w=>w.num)[0];if(num){let s=document.createElement('small');s.textContent=num;d.append(s);}let input=document.createElement('input');input.type='text';input.autocomplete='off';input.spellcheck=false;input.maxLength=2;input.setAttribute('aria-label',t.cell+' '+q.words.map(id=>words.find(w=>w.id===id).num).join(' / ')+', '+t.row+' '+(r+1)+', '+t.column+' '+(c+1));input.lang=locale.id;input.dataset.key=k;d.append(input);grid.append(d);map.set(k,{input,d});input.addEventListener('focus',()=>{if(!chosen||!E.cells(chosen).some(t=>t.r===r&&t.c===c))select(words.find(w=>q.words.includes(w.id)));pos=E.cells(chosen).findIndex(t=>t.r===r&&t.c===c);highlight();});input.addEventListener('click',()=>{if(q.words.length>1&&options.lastKey===k){select(words.find(w=>q.words.includes(w.id)&&w.id!==chosen.id));pos=E.cells(chosen).findIndex(t=>t.r===r&&t.c===c);}options.lastKey=k;highlight();});input.addEventListener('input',()=>{let v=E.norm(input.value,p.foldYo!==false);if(v)type(v.slice(-1));else{answers[k]='';updateLetters();}});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();check();}else if(e.key==='Backspace'){e.preventDefault();backspace();}else if(e.key===' '){e.preventDefault();let ids=b.get(k).words;let next=words.find(w=>ids.includes(w.id)&&w.id!==chosen.id);if(next){select(next);focus();}}else if(e.key.startsWith('Arrow')){e.preventDefault();pos=Math.max(0,Math.min(chosen.answer.length-1,pos+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)));focus();}else if(e.key==='Tab'&&!e.shiftKey){e.preventDefault();nextWord();focus();}});}
function say(state,text){if(!p.catBubble)bubble.style.display='none';const defaults={idle:t.idle,correct:t.correct,onelife:t.oneLife,wrong:t.wrong,hint:t.help,victory:t.won,defeat:t.lost,timeout:t.timeout,lowtime:t.lowTime};bubble.textContent=text||p.messages?.[state]||defaults[state]||defaults.idle;const zone=host.querySelector('.cw-cat-zone');zone.dataset.state=state;const image=zone.querySelector('img'),src=catSource(state);if(image.getAttribute('src')!==src)image.src=src;zone.classList.remove('happy','sad');if(['correct','victory'].includes(state)){void zone.offsetWidth;zone.classList.add('happy');}if(['wrong','onelife','defeat','timeout'].includes(state))zone.classList.add('sad');}
